def slope_and_intercept(x1, y1, x2, y2):
    slope = (lambda a1, b1, a2, b2: (b2 - b1) / (a2 - a1))(x1, y1, x2, y2)
    intercept = (lambda a1, b1, m: b1 - m * a1)(x1, y1, slope)
    return (slope, intercept)
